/**
 * Every colour the UI uses is a token, --dm-c-<hex>, that defaults to its own value (tokens.css, generated by
 * scripts/dev/tokenize-colours.py). A palette recomputes them from its seeds, by what the colour is:
 *
 *  - a grey (slate, gray, the dark surfaces, white, black) follows the palette's own light-to-dark range,
 *    at the same lightness: #1e1e1e sits near the ground, #94a3b8 halfway, #f8fafc near the text;
 *  - a colour of the accent / success / warning / error / info family (by hue) becomes that seed, at the
 *    same shade relative to the family's base (indigo-300 stays "three steps lighter than the accent");
 *  - identity colours (violet, pink, orange, teal, lime...) keep their hue unless the palette sets one.
 */
import { COLOUR_TOKENS } from './tokens.generated';
import { parseHex, toHsl, shiftLightness, mix, isDarkColour } from './colour';
import type { AppSeeds } from './palette';

/** Families a palette can recolour; seeds for the first five, optional identity colours for the rest. */
export type Family = 'accent' | 'success' | 'warning' | 'error' | 'info' | 'violet' | 'pink' | 'orange' | 'teal' | 'lime';
export const IDENTITY_FAMILIES: Family[] = ['violet', 'pink', 'orange', 'teal', 'lime'];

/** The base shade of each family in the stylesheet (Tailwind 500), which the seed stands in for. */
const BASE: Record<Family, string> = {
  accent: '#6366f1', success: '#22c55e', warning: '#f59e0b', error: '#ef4444', info: '#3b82f6',
  violet: '#8b5cf6', pink: '#ec4899', orange: '#f97316', teal: '#14b8a6', lime: '#84cc16',
};

export function familyOf(hex: string): Family | 'neutral' {
  const c = parseHex(hex);
  if (!c) return 'neutral';
  const max = Math.max(c.r, c.g, c.b), min = Math.min(c.r, c.g, c.b);
  if ((max - min) / 255 < 0.16) return 'neutral';
  const { h } = toHsl(c);
  if (h >= 345 || h < 12) return 'error';
  if (h < 30) return 'orange';
  if (h < 62) return 'warning';
  if (h < 85) return 'lime';
  if (h < 165) return 'success';
  if (h < 190) return 'teal';
  if (h < 222) return 'info';
  if (h < 250) return 'accent';
  if (h < 300) return 'violet';
  return 'pink';
}

const lightness = (hex: string) => { const c = parseHex(hex); return c ? toHsl(c).l : 0.5; };

/** The family colour at the shade `hex` had relative to the family base. */
function shade(seed: string, family: Family, hex: string): string {
  const target = lightness(seed) + (lightness(hex) - lightness(BASE[family]));
  return shiftLightness(seed, Math.min(0.98, Math.max(0.03, target)));
}

/** Values for every token, for one half (dark or light seeds) of a palette. */
export function tokenValues(seeds: AppSeeds, identity: Partial<Record<Family, string>> = {}): Record<string, string> {
  const onDark = isDarkColour(seeds.ground);
  const darkEnd = onDark ? seeds.ground : seeds.text;
  const lightEnd = onDark ? seeds.text : seeds.surface;
  const seedOf: Partial<Record<Family, string>> = {
    accent: seeds.accent, success: seeds.success, warning: seeds.warning, error: seeds.error, info: seeds.info, ...identity,
  };
  const out: Record<string, string> = {};
  for (const hex6 of COLOUR_TOKENS) {
    const hex = `#${hex6}`;
    const fam = familyOf(hex);
    let v: string | undefined;
    if (fam === 'neutral') {
      // lightness 0.06..0.97 -> the palette's dark end .. light end
      const p = Math.min(1, Math.max(0, (lightness(hex) - 0.06) / 0.91));
      v = mix(lightEnd, darkEnd, p);
    } else if (seedOf[fam]) {
      v = shade(seedOf[fam]!, fam, hex);
    }
    if (v) out[`--dm-c-${hex6}`] = v;
  }
  return out;
}
